DROP TABLE IF EXISTS `coin`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `coin` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '币种id',
  `sid` varchar(64) NOT NULL DEFAULT '' COMMENT '币种sid',
  `name` varchar(32) NOT NULL DEFAULT '' COMMENT '币种名',
  `optional_name` varchar(32) NOT NULL DEFAULT '',
  `nickname` json DEFAULT NULL,
  `icon` varchar(128) NOT NULL DEFAULT '' COMMENT '币种图标地址',
  `introduce` json DEFAULT NULL,
  `official` varchar(128) NOT NULL DEFAULT '' COMMENT '官网地址',
  `paper` varchar(255) NOT NULL DEFAULT '' COMMENT '白皮书地址',
  `exchange` smallint(6) NOT NULL DEFAULT '0' COMMENT '上架交易所数量',
  `platform` varchar(64) DEFAULT '' COMMENT '币种平台',
  `chain` varchar(16) DEFAULT NULL,
  `release` date DEFAULT NULL COMMENT '发行时间',
  `price` decimal(20,6) unsigned DEFAULT NULL COMMENT '众筹价格',
  `area_search` text COMMENT '区块查询url',
  `publish_count` double NOT NULL DEFAULT '0' COMMENT '发行总量',
  `circulate_count` double NOT NULL DEFAULT '0' COMMENT '流通总量',
  `decimals` int(11) NOT NULL DEFAULT '0' COMMENT '精度',
  `address` varchar(255) NOT NULL DEFAULT '' COMMENT '合约地址',
  `platform_id` json DEFAULT NULL,
  `treaty` tinyint(3) unsigned NOT NULL DEFAULT '1' COMMENT '合约类型\n1、token\n2、coins',
  `is_nft` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 普通币种 1 NFT',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `id_UNIQUE` (`id`) USING BTREE,
  KEY `name` (`name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=739 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='币种表';
