  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作员Id',
  `user_name` char(20) NOT NULL DEFAULT '' COMMENT '操作员name',
  `platform_id` int(10) unsigned NOT NULL DEFAULT '0',
  `ip` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '操作地址Ip',
  `operation` varchar(50) NOT NULL DEFAULT '' COMMENT '操作 增删改',
  `business` varchar(50) NOT NULL DEFAULT '' COMMENT '业务名称',
  `table` varchar(45) NOT NULL DEFAULT '' COMMENT '直接相关表（一个）',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `id_UNIQUE` (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=372200 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
