DROP TABLE IF EXISTS `wallet_red_packet`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wallet_red_packet` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `packet_id` char(40) NOT NULL DEFAULT '',
  `live_id` int(10) unsigned NOT NULL DEFAULT '0',
  `avatar` varchar(100) NOT NULL DEFAULT '',
  `receive` json DEFAULT NULL,
  `user_id` varchar(20) NOT NULL DEFAULT '0' COMMENT '平台用户UID',
  `user_name` char(10) NOT NULL DEFAULT '' COMMENT '平台用户名',
  `user_mobile` char(11) NOT NULL DEFAULT '' COMMENT '平台用户手机号',
  `platform_id` varchar(10) NOT NULL DEFAULT '0' COMMENT '平台标示码',
