  `remain` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '未收红包个数',
  `status` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '红包状态\n1:生效中2:已领取完3:过期已退回4:已完成',
  `remark` varchar(45) NOT NULL COMMENT '红包说明',
  `create_at` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_at` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `expire_at` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '过期时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `id_UNIQUE` (`id`) USING BTREE,
  UNIQUE KEY `packet_id_UNIQUE` (`packet_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
